curl -s -X POST "https://slack.com/api/users.list" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{}' | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for user in data['members']:
        if 'diego' in user['real_name'].lower() or 'alvarez' in user.get('real_name', '').lower():
            print(json.dumps(user, indent=2))
else:
    print('Error:', data)
"

curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{"types": "private_channel", "exclude_archived": true}' | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        purpose = ch.get('purpose', {}).get('value', '')
        print(f\"ID: {ch['id']}, Name: {ch['name']}, Purpose: {purpose}\")
else:
    print('Error:', data)
"
